import React, { useState, useEffect } from "react";
import Map from "./Map";

function AdminPanel({
    enterprises,
    onAdd,
    onEdit,
    onDelete,
    addMode,
    setAddMode,
    pendingCoords,
    setPendingCoords,
}) {
    const [editing, setEditing] = useState(null);
    const [adding, setAdding] = useState(false);
    const [form, setForm] = useState({
        id: "",
        name: "",
        image: "",
        x: "",
        y: "",
        shortDescription: "",
        fullDescription: "",
    });

    useEffect(() => {
        if (pendingCoords && addMode) {
            setAdding(true);
            setForm((f) => ({
                ...f,
                x: pendingCoords.x,
                y: pendingCoords.y,
            }));
        }
    }, [pendingCoords, addMode]);

    const handleMarkerDrag = (coords) => {
        setForm((f) => ({
            ...f,
            x: coords.x,
            y: coords.y,
        }));
    };

    const handleEditClick = (enterprise) => {
        setEditing(enterprise.id);
        setPendingCoords(null);
        setAdding(false);
        setForm(enterprise);
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (editing) {
            onEdit(form);
        } else {
            onAdd({ ...form, id: Date.now().toString() });
        }
        setForm({
            id: "",
            name: "",
            image: "",
            x: "",
            y: "",
            shortDescription: "",
            fullDescription: "",
        });
        setEditing(null);
        setPendingCoords(null);
        setAdding(false);
        setAddMode(false);
    };

    const handleAddMode = () => {
        setAddMode(true);
        setPendingCoords(null);
        setEditing(null);
        setAdding(false);
        setForm({
            id: "",
            name: "",
            image: "",
            x: "",
            y: "",
            shortDescription: "",
            fullDescription: "",
        });
    };

    const handleCancel = () => {
        setEditing(null);
        setPendingCoords(null);
        setAdding(false);
        setAddMode(false);
        setForm({
            id: "",
            name: "",
            image: "",
            x: "",
            y: "",
            shortDescription: "",
            fullDescription: "",
        });
    };

    return (
        <div style={{ padding: 20 }}>
            <h2>Админ-панель</h2>
            <button onClick={handleAddMode} disabled={addMode || adding}>
                {addMode ? "Кликните на карту" : "Добавить завод на карту"}
            </button>

            {addMode && !adding && (
                <div style={{ margin: "16px 0", border: "2px dashed #aaa" }}>
                    <p>Кликните на карту для выбора координат расположения завода.</p>
                    <Map
                        plants={enterprises}
                        onMapClick={(coords) => {
                            setPendingCoords(coords);
                            setAddMode(true);
                        }}
                        adminAddMode={addMode}
                    />
                </div>
            )}

            {adding && (
                <div>
                    <Map
                        plants={[]}
                        editingPlant={form}
                        onMarkerDrag={handleMarkerDrag}
                        adminEditMode={true}
                    />
                    <form onSubmit={handleSubmit} style={{ marginTop: 16 }}>
                        <input
                            placeholder="Название"
                            value={form.name}
                            onChange={(e) => setForm({ ...form, name: e.target.value })}
                            required
                        />
                        <input
                            placeholder="Ссылка на картинку"
                            value={form.image}
                            onChange={(e) => setForm({ ...form, image: e.target.value })}
                            required
                        />
                        <input
                            placeholder="X (0-100%)"
                            type="number"
                            value={form.x}
                            onChange={(e) => setForm({ ...form, x: Number(e.target.value) })}
                            required
                            min="0"
                            max="100"
                        />
                        <input
                            placeholder="Y (0-100%)"
                            type="number"
                            value={form.y}
                            onChange={(e) => setForm({ ...form, y: Number(e.target.value) })}
                            required
                            min="0"
                            max="100"
                        />
                        <input
                            placeholder="Краткое описание"
                            value={form.shortDescription}
                            onChange={(e) =>
                                setForm({ ...form, shortDescription: e.target.value })
                            }
                            required
                        />
                        <textarea
                            placeholder="Полное описание"
                            value={form.fullDescription}
                            onChange={(e) =>
                                setForm({ ...form, fullDescription: e.target.value })
                            }
                            required
                        />
                        <button type="submit">Добавить</button>
                        <button type="button" onClick={handleCancel}>
                            Отмена
                        </button>
                    </form>
                </div>
            )}

            {editing && (
                <div>
                    <Map
                        plants={plants}
                        editingPlant={form}
                        onMarkerDrag={handleMarkerDrag}
                        adminEditMode={true}
                    />
                    <form onSubmit={handleSubmit} style={{ marginTop: 16 }}>
                        <input
                            placeholder="Название"
                            value={form.name}
                            onChange={(e) => setForm({ ...form, name: e.target.value })}
                            required
                        />
                        <input
                            placeholder="Ссылка на картинку"
                            value={form.image}
                            onChange={(e) => setForm({ ...form, image: e.target.value })}
                            required
                        />
                        <input
                            placeholder="X (0-100%)"
                            type="number"
                            value={form.x}
                            onChange={(e) => setForm({ ...form, x: Number(e.target.value) })}
                            required
                            min="0"
                            max="100"
                        />
                        <input
                            placeholder="Y (0-100%)"
                            type="number"
                            value={form.y}
                            onChange={(e) => setForm({ ...form, y: Number(e.target.value) })}
                            required
                            min="0"
                            max="100"
                        />
                        <input
                            placeholder="Краткое описание"
                            value={form.shortDescription}
                            onChange={(e) =>
                                setForm({ ...form, shortDescription: e.target.value })
                            }
                            required
                        />
                        <textarea
                            placeholder="Полное описание"
                            value={form.fullDescription}
                            onChange={(e) =>
                                setForm({ ...form, fullDescription: e.target.value })
                            }
                            required
                        />
                        <button type="submit">Сохранить</button>
                        <button type="button" onClick={handleCancel}>
                            Отмена
                        </button>
                    </form>
                </div>
            )}

            <h3>Список заводов</h3>
            <ul>
                {plants.map((plant) => (
                    <li key={plant.id}>
                        <b>{plant.name}</b>
                        <button onClick={() => handleEditClick(plant)}>
                            Редактировать
                        </button>
                        <button onClick={() => onDelete(plant.id)}>Удалить</button>
                    </li>
                ))}
            </ul>
        </div>
    );
}

export default AdminPanel;
